#include <bits/stdc++.h>
using namespace std;

constexpr int MOD=998244353;
inline void addmod(int &x, int y){
    x+=y;
    if(x>=MOD) x-=MOD;
}

int main() {
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<vector<int>> positions(n+1);
        for(int i=1;i<=n;++i){
            int a;
            cin>>a;
            positions[a].push_back(i);
        }
        vector<int> dp(n+1),next_dp(n+1);
        dp[0]=1;
        for(int value=1;value<=n;++value){
            fill(next_dp.begin(),next_dp.end(),0);
            for(int left=0;left<value;++left){
                if(dp[left]==0) continue;
            int l=left+1;
            int r=n-value+1+left;
            bool canleft=true;
            bool canright=(l<r);
            for(int i:positions[value]){
                int smallerprefix=min(i,left)+max(0,i-r);
                int smallersuffix=value-1-min(i-1,left)-max(0,i-1-r);
                bool prefixok=(smallerprefix==(i-1)/2);
                bool suffixok=(smallersuffix==(n-i)/2);
                canleft=canleft && ((l<=i && prefixok) || (l>=i && suffixok));
                canright=canright &&((r<=i&&prefixok)||(r>=i && suffixok));
                if(!canleft && !canright) break;
                  
            }
            if(canleft) addmod(next_dp[left+1],dp[left]);
            if(canright) addmod(next_dp[left],dp[left]);
            }
            dp.swap(next_dp);
        
        }
        int answer=0;
        for(int ways : dp)
          addmod(answer,ways);
        cout<<answer<<'\n';
    }
    return 0;
	

}
